function injectModCSS() {
  if (document.getElementById('v3-mod-css-pet')) return;
  const st = document.createElement('style');
  st.id = 'v3-mod-css-pet';
  st.dataset.mod = 'pet';
  st.textContent = MOD_CSS;
  (document.head || document.documentElement).appendChild(st);
}
function removeModCSS(force) {
  /* 设置卡片还在页面上就先留着（未装配时也能先改设置，卡片得有样式）；
     卡片被销毁时宿主会调用它登记的清理函数，那时 force=true 再收。 */
  if (!force && document.querySelector('.v3-card[data-id="pet"]')) return;
  const st = document.getElementById('v3-mod-css-pet');
  if (st && st.parentNode) st.parentNode.removeChild(st);
}

