    const actWrap = U.el('details', 'v3-help');
    actWrap.appendChild(U.el('summary', null, '展开 32 张动作帧（' + Object.keys(ACT_IMG).length + ' / 32）'));
    const actBd = U.el('div', 'v3-help-bd');
    const grid = U.el('div');
    grid.style.cssText = 'display:flex;flex-wrap:wrap;gap:7px';
