      th.style.cssText += ';width:64px;height:64px;flex:0 0 64px;margin:0 auto;cursor:pointer';
      th.style.backgroundImage = 'url("' + ACT_SRC[slot] + '")';
      th.title = '点一下看这个动作';
      th.onclick = function () { pet.actKey = slot; pet.actT = 4; };
      cell.appendChild(th);
