  const ACT_LABEL = {
    joy: '元气问候', wake: '叫起床', tsundere: '傲娇否认', huff: '生气扭头', worry: '嘴硬关心',
    scold: '嫌弃说教', yawn: '打哈欠', praise: '被夸受用', care: '让人放松', water: '催喝水',
    teach: '讲知识', comfort: '安慰', thanks: '道谢', nag: '唠叨别熬夜', celebrate: '庆祝',
    wait: '等人的样子', cocky: '不服气', welcome: '欢迎回来', sulk: '赌气不理', stroll: '想出门走走',
    spin: '转圈炫耀', sigh: '叹气', hail: '喊人', wail: '哭诉', explain2: '认真解释',
    relax: '放松', chat: '日常闲聊', sleepy: '犯困', cheer: '给你打气', inspect: '凑近看',
    sorry: '道歉', holdback: '忍住不哭'
  };
  function randId() { return 'u' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6); }
  function refreshPanel() { if (V3.UI && V3.UI.render) uiRefresh(); }

  /* 【V3.3】动作帧「归位表」：拖进来的图先停在这里，由使用者逐张指定它顶掉 32 个动作里的哪一个。
     放在模块作用域（不在 buildSpritePanel 里），这样设置面板重绘也不会把待归位的图弄丢。 */
  let actPending = [];
  function renderActPending(host) {
    host.innerHTML = '';
    if (!actPending.length) return;
    const slots = Object.keys(ACT_SRC);
    const box = U.el('div', 'v3-tagbox');
    box.appendChild(U.el('div', 'v3-grp', '归位表：每张图顶掉哪个动作？'));
    actPending.forEach(function (p) {
      const row = U.el('div', 'v3-tgrow');
      const th = U.el('div', 'v3-ithumb');
      th.style.backgroundImage = 'url("' + p.src + '")';
      row.appendChild(th);
      const nm = U.el('span', null, U.esc(String(p.name || '').slice(0, 16)));
      nm.style.cssText = 'flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;'
        + 'white-space:nowrap;font-size:10.5px;color:#8a7a5e';
      row.appendChild(nm);
      const sel = U.el('select');
      sel.style.cssText = 'flex:0 0 128px;border:1px solid rgba(168,128,46,.35);border-radius:5px;'
        + 'background:#fffdf6;color:inherit;font-size:10.5px;padding:3px 4px';
      slots.forEach(function (s) {
        const o = U.el('option', null, U.esc(actLabelOf(s))); o.value = s;
        if (s === p.slot) o.selected = true;
        sel.appendChild(o);
      });
      sel.onchange = function () { p.slot = sel.value; };
      row.appendChild(sel);
      const bd = U.el('button', 'v3-mini', '✕');
      bd.onclick = function () { actPending.splice(actPending.indexOf(p), 1); renderActPending(host); };
      row.appendChild(bd);
      box.appendChild(row);
    });
    const bar = U.el('div');
    bar.style.cssText = 'display:flex;gap:8px;margin-top:8px;flex-wrap:wrap';
    const bOk = U.el('button', 'v3-btn pri', '全部归位（' + actPending.length + ' 张）');
    bOk.onclick = function () {
      const n = actPending.length;
      const jobs = actPending.map(function (p) {
        return loadActImage(p.slot, p.src).then(function (ok) {
          if (ok) { U.idb.put('pet:actframe:' + p.slot, p.src).catch(function () {}); p.done = true; }
          return ok;
        });
      });
      Promise.all(jobs).then(function () {
        actPending = actPending.filter(function (p) { return !p.done; });
        toast('已归位 ' + (n - actPending.length) + ' 张动作帧', 2600, 'ok');
        refreshPanel();
      });
    };
    const bClr = U.el('button', 'v3-btn dgr', '全部取消');
    bClr.onclick = function () { actPending = []; refreshPanel(); };
    bar.appendChild(bOk); bar.appendChild(bClr);
    box.appendChild(bar);
    host.appendChild(box);
  }

  /* 【V3.3】形象图「归位表」：拖进来的图要是文件名认不出槽位，就停下来让使用者自己挑。 */
  let spritePending = [];
  function renderSpritePending(host) {
    host.innerHTML = '';
    if (!spritePending.length) return;
    const box = U.el('div', 'v3-tagbox');
    box.appendChild(U.el('div', 'v3-grp', '归位表：这几张认不出文件名，你指定它顶掉哪个槽位'));
    spritePending.forEach(function (p) {
      const row = U.el('div', 'v3-tgrow');
      const th = U.el('div', 'v3-ithumb');
      th.style.backgroundImage = 'url("' + p.src + '")';
      row.appendChild(th);
      const nm = U.el('span', null, U.esc(String(p.name || '').slice(0, 16)));
      nm.style.cssText = 'flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;'
        + 'white-space:nowrap;font-size:10.5px;color:#8a7a5e';
      row.appendChild(nm);
      const sel = U.el('select');
      sel.style.cssText = 'flex:0 0 150px;border:1px solid rgba(168,128,46,.35);border-radius:5px;'
        + 'background:#fffdf6;color:inherit;font-size:10.5px;padding:3px 4px';
      SPRITE_SLOTS.forEach(function (s) {
        const o = U.el('option', null, U.esc(slotName(s))); o.value = s.key;
        if (s.key === p.slot) o.selected = true;
        sel.appendChild(o);
      });
      sel.onchange = function () { p.slot = sel.value; };
      row.appendChild(sel);
      const bd = U.el('button', 'v3-mini', '✕');
      bd.onclick = function () { spritePending.splice(spritePending.indexOf(p), 1); refreshPanel(); };
      row.appendChild(bd);
      box.appendChild(row);
    });
    const bar = U.el('div');
    bar.style.cssText = 'display:flex;gap:8px;margin-top:8px;flex-wrap:wrap';
    const bOk = U.el('button', 'v3-btn pri', '全部归位（' + spritePending.length + ' 张）');
    bOk.onclick = function () {
      const n = spritePending.length;
      Promise.all(spritePending.map(function (p) {
        return loadSprite(p.slot, p.src).then(function () {
          U.idb.put('pet:sprite:' + p.slot, p.src).catch(function () {});
          p.done = true;
        }).catch(function () {});
      })).then(function () {
        spritePending = spritePending.filter(function (p) { return !p.done; });
        toast('已归位 ' + (n - spritePending.length) + ' 张形象图', 2400, 'ok');
        refreshPanel();
      });
    };
    const bClr = U.el('button', 'v3-btn dgr', '全部取消');
    bClr.onclick = function () { spritePending = []; refreshPanel(); };
    bar.appendChild(bOk); bar.appendChild(bClr);
    box.appendChild(bar);
    host.appendChild(box);
  }
  function ASSET_DEBUG() {
    return {
      voice: VOICE.length,
      acts: Object.keys(ACT_IMG).length,
      slots: SPRITE_SLOTS.filter(function (s) { return !!SPRITE[s.key]; }).length,
      actSlots: Object.keys(ACT_IMG),
      builtinSprites: Object.keys(SPRITE_BUILTIN).length,
      voiceWithAudio: VOICE.filter(function (r) { return !!r.src; }).length,
      userEdited: VOICE.filter(function (r) { return r.user; }).length
    };
  }

  function pickAudioFile(cb) {
    const f = U.el('input');
    f.type = 'file'; f.accept = 'audio/*';
    f.onchange = function () { if (f.files && f.files[0]) cb(f.files[0]); };
    f.click();
  }
  function pickOneImage(cb) {
    const f = U.el('input');
    f.type = 'file'; f.accept = 'image/*';
    f.onchange = function () { if (f.files && f.files[0]) cb(f.files[0]); };
    f.click();
  }
  function readAsDataURL(file) {
    return new Promise(function (res) {
      const r = new FileReader();
      r.onload = function () { res(String(r.result || '')); };
      r.onerror = function () { res(''); };
      r.readAsDataURL(file);
    });
  }
  function audioDuration(dataUrl) {
    return new Promise(function (res) {
      try {
        const a = new Audio();
        a.preload = 'metadata';
        a.onloadedmetadata = function () { res(isFinite(a.duration) ? a.duration : 2.4); };
        a.onerror = function () { res(2.4); };
        a.src = dataUrl;
        setTimeout(function () { res(2.4); }, 2500);
      } catch (e) { res(2.4); }
    });
  }

  /* ---- 语音台词（音频 + 配套动作帧，一一对应）---- */
  function buildVoicePanel(host) {
    if (!ctxRef) return null;
    const box = U.el('div');
    box.innerHTML = '<div class="v3-note">每一行是<b>一对</b>：'
      + '<b>台词音频</b>（文件名/内容就是这句台词）＋ <b>配套动作图</b>（说这句时摆的动作）。'
      + '编号一一对应，<b>播哪句就切哪张动作</b>。内置 32 组「主星女仆」原声，'
      + '你可以逐条换成自己的录音和自己的画。当前 <b>' + VOICE.length + '</b> 组，'
      + '动作帧已载入 <b>' + Object.keys(ACT_IMG).length + '</b> 张。</div>';

    const wrap = U.el('details', 'v3-help');
    const sum = U.el('summary', null, '展开 32 组语音台词（点开逐条替换 / 试听）');
    const bd = U.el('div', 'v3-help-bd');
    wrap.appendChild(sum); wrap.appendChild(bd);
    box.appendChild(wrap);

    const list = U.el('div');
    bd.appendChild(list);

    VOICE.forEach(function (rec, idx) {
      const row = U.el('div', 'v3-line');
      row.appendChild(U.el('div', 'v3-line-n', String(idx + 1)));
      const th = U.el('div', 'v3-spr-t');
      th.style.cssText += ';width:34px;height:34px;flex:0 0 34px';
      if (ACT_SRC[rec.slot]) th.style.backgroundImage = 'url("' + ACT_SRC[rec.slot] + '")';
      else th.textContent = '空';
      row.appendChild(th);
      const ta = U.el('textarea');
      ta.value = rec.text || '';
      ta.rows = 1;
      ta.onchange = function () { rec.text = ta.value.trim(); rec.user = true; persistVoice(); };
      row.appendChild(ta);
      const ctl = U.el('div', 'v3-spr-c');
      ctl.style.alignItems = 'center';
      const bPlay = U.el('button', 'v3-mini', '▶');
      bPlay.title = '试听 + 摆这个动作';
      bPlay.onclick = function () { speakVoice(rec); };
      ctl.appendChild(bPlay);
      const bAud = U.el('button', 'v3-mini', '♪');
      bAud.title = '导入这一句的音频（推荐 wav / mp3，越短越好）';
      bAud.onclick = function () {
        pickAudioFile(function (file) {
          readAsDataURL(file).then(function (d) {
            if (!d) { toast('读不出这个音频', 2400, 'err'); return; }
            audioDuration(d).then(function (dur) {
              rec.src = d; rec.dur = Math.round(dur * 100) / 100; rec.user = true;
              /* 文件名（去掉扩展名与开头编号）也顺手填成台词 */
              const nm = String(file.name).replace(/\.[^.]+$/, '').replace(/^\s*\d+\s*[_\-.]\s*/, '').trim();
              if (nm) { rec.text = nm; ta.value = nm; }
              persistVoice();
              toast('第 ' + (idx + 1) + ' 句已换成你的音频（' + rec.dur + 's）', 2600, 'ok');
            });
          });
        });
      };
      ctl.appendChild(bAud);
      const bImg = U.el('button', 'v3-mini', '图');
      bImg.title = '导入这一句的配套动作图';
      bImg.onclick = function () {
        pickOneImage(function (file) {
          readAsDataURL(file).then(function (d) {
            if (!d) return;
            loadActImage(rec.slot, d).then(function () {
              rec.user = true; persistVoice();
              th.style.backgroundImage = 'url("' + d + '")';
              th.textContent = '';
              toast('第 ' + (idx + 1) + ' 句的动作图已更新', 2200, 'ok');
            });
          });
        });
      };
      ctl.appendChild(bImg);
      const bDel = U.el('button', 'v3-mini', '✕');
      bDel.title = '删掉这一组（台词 + 音频 + 动作图）';
      bDel.onclick = function () {
        const i = VOICE.indexOf(rec);
        if (i >= 0) VOICE.splice(i, 1);
        persistVoice();
        refreshPanel();
      };
      ctl.appendChild(bDel);
      row.appendChild(ctl);
      list.appendChild(row);
    });

    /* ＋ 新增一组 */
    const add = U.el('div', 'v3-line');
    add.appendChild(U.el('div', 'v3-line-n', '＋'));
    const addTa = U.el('textarea');
    addTa.placeholder = '新的一句话……';
    addTa.rows = 1;
    add.appendChild(addTa);
    const addCtl = U.el('div', 'v3-spr-c');
    addCtl.style.alignItems = 'center';
    let pendAudio = '', pendDur = 2.4, pendImg = '';
    const bA = U.el('button', 'v3-mini', '♪');
    bA.title = '先选音频';
    const bI = U.el('button', 'v3-mini', '图');
    bI.title = '再选动作图';
    const bAdd = U.el('button', 'v3-mini', '＋');
    bAdd.title = '加进去';
    bA.onclick = function () {
      pickAudioFile(function (f) {
        readAsDataURL(f).then(function (d) {
          pendAudio = d;
          const nm = String(f.name).replace(/\.[^.]+$/, '').replace(/^\s*\d+\s*[_\-.]\s*/, '').trim();
          if (nm && !addTa.value.trim()) addTa.value = nm;
          audioDuration(d).then(function (x) { pendDur = x; toast('音频已就绪（' + Math.round(x * 100) / 100 + 's）', 2000, 'ok'); });
        });
      });
    };
    bI.onclick = function () { pickOneImage(function (f) { readAsDataURL(f).then(function (d) { pendImg = d; toast('动作图已就绪', 1800, 'ok'); }); }); };
    bAdd.onclick = function () {
      const text = addTa.value.trim();
      if (!text) { toast('先写一句台词', 2200, 'err'); return; }
      const rid = randId();
      const slot = 'u_' + rid;
      if (pendImg) loadActImage(slot, pendImg);
      VOICE.push({ id: rid, slot: slot, text: text, dur: pendDur || 2.4, src: pendAudio || '', user: true });
      persistVoice();
      toast('已加入第 ' + VOICE.length + ' 组', 2000, 'ok');
      refreshPanel();
    };
    addCtl.appendChild(bA); addCtl.appendChild(bI); addCtl.appendChild(bAdd);
    add.appendChild(addCtl);
    bd.appendChild(add);

    const bar = U.el('div');
    bar.style.cssText = 'display:flex;gap:8px;margin-top:8px;flex-wrap:wrap';
    const bR1 = U.el('button', 'v3-btn', '全部恢复内置 32 组');
    bR1.onclick = function () {
      VOICE.length = 0;
      VOICE_BAK.forEach(function (r) {
        VOICE.push({ id: r.id, slot: r.slot, text: r.text, dur: r.dur || 2.4, src: r.src, user: false });
      });
      const acts = (typeof PET_ACT_SRC !== 'undefined' && PET_ACT_SRC) || {};
      Object.keys(acts).forEach(function (s) { loadActImage(s, acts[s]); });
      persistVoice();
      toast('已恢复内置语音台词包', 2200, 'ok');
      refreshPanel();
    };
    const bR2 = U.el('button', 'v3-btn', '关闭语音（只说话不出声）');
    bR2.onclick = function () { ctxRef.settings.set('voiceOn', false); uiRefresh(); };
    bar.appendChild(bR1); bar.appendChild(bR2);
    bd.appendChild(bar);

    host.appendChild(box);
    return null;
  }

  /* ---- 台词设置（一句一行，可增删改）---- */
  function linesArray() {
    const raw = ctxRef ? mg('lines', '') : '';
    return raw ? String(raw).split('\n') : [];
  }
  function setLines(arr) { ms('lines', arr.join('\n')); }
  function buildLinesPanel(host) {
    if (!ctxRef) return null;
    const arr = linesArray();
    const box = U.el('div');
    box.innerHTML = '<div class="v3-grp">台词设置（一句一行，可改可删）</div>'
      + '<div class="v3-note">这里的台词<b>优先出场</b>：女仆闲着没事时会先从这几句里挑。'
      + '一句一行，可以直接改、可以删。想让她说什么，就写什么。'
      + '以 <code>#</code> 开头的行会被忽略（当注释用）。当前 <b>' + arr.length + '</b> 句。</div>';

    const wrap = U.el('details', 'v3-help');
    wrap.appendChild(U.el('summary', null, '展开台词列表（' + arr.length + ' 句）'));
    const bd = U.el('div', 'v3-help-bd');
    const list = U.el('div');
    arr.forEach(function (ln, i) {
      const row = U.el('div', 'v3-line');
      row.appendChild(U.el('div', 'v3-line-n', String(i + 1)));
      const ta = U.el('textarea');
      ta.value = ln; ta.rows = 1;
      ta.onchange = function () { arr[i] = ta.value.replace(/\n/g, ' '); setLines(arr); };
      row.appendChild(ta);
      const ctl = U.el('div', 'v3-spr-c');
      ctl.style.alignItems = 'center';
      const bD = U.el('button', 'v3-mini', '✕');
      bD.onclick = function () { arr.splice(i, 1); setLines(arr); refreshPanel(); };
      ctl.appendChild(bD);
      row.appendChild(ctl);
      list.appendChild(row);
    });
    bd.appendChild(list);

    /* ＋ 加号窗口 */
    const add = U.el('div', 'v3-addrow');
    const inp = U.el('input');
    inp.placeholder = '＋ 写一句新台词，回车加入';
    const b = U.el('button', 'v3-btn pri', '加入');
    const doAdd = function () {
      const v = inp.value.trim();
      if (!v) return;
      arr.push(v); setLines(arr);
      inp.value = '';
      refreshPanel();
    };
    b.onclick = doAdd;
    inp.addEventListener('keydown', function (e) { e.stopPropagation(); if (e.key === 'Enter') doAdd(); });
    add.appendChild(inp); add.appendChild(b);
    bd.appendChild(add);

    const bar = U.el('div');
    bar.style.cssText = 'display:flex;gap:8px;margin-top:8px;flex-wrap:wrap';
    const bSeed = U.el('button', 'v3-btn', '塞入女仆自带的几句');
    bSeed.onclick = function () {
      const seed = (typeof IDLE_LINES !== 'undefined' ? IDLE_LINES : []).slice(0, 12);
      const cur = linesArray().concat(seed).filter(function (s, i, a) { return s && a.indexOf(s) === i; });
      setLines(cur); refreshPanel();
      toast('已加入 ' + seed.length + ' 句', 1800, 'ok');
    };
    const bClr = U.el('button', 'v3-btn dgr', '清空');
    bClr.onclick = function () { setLines([]); refreshPanel(); };
    bar.appendChild(bSeed); bar.appendChild(bClr);
    bd.appendChild(bar);

    wrap.appendChild(bd);
    box.appendChild(wrap);
    host.appendChild(box);
    return null;
  }

  /* ---- 气泡类型（＋ 自己导入一种）---- */
  function buildBubblePanel(host) {
    if (!ctxRef) return null;
    const cur = (ctxRef && mg('bubbleStyle', 'b1')) || 'b1';
    const img = BUBBLE_IMG;
    const box = U.el('div');
    box.innerHTML = '<div class="v3-note">现在一共有 3 种内置气泡：'
      + '<b>便签</b>（默认）· <b>羊皮卷</b>（跟着地图的质感走）· <b>星棱水晶</b>（夜里最清楚）。'
      + '下面是第 4 种「<b>你自己的图</b>」—— 点 ＋ 传一张 PNG / JPG，它会作为气泡底板拉伸铺满。</div>';

    const prev = U.el('div');
    prev.style.cssText = 'display:flex;gap:10px;flex-wrap:wrap;margin:6px 0';
    [['b1', '便签'], ['b2', '羊皮卷'], ['b3', '星棱水晶'], ['b4', '你自己的图']].forEach(function (pair) {
      const cell = U.el('div');
      cell.style.cssText = 'flex:1 1 46%;min-width:130px;padding:8px;border:1px solid rgba(168,128,46,.35);'
        + 'border-radius:8px;background:rgba(255,255,255,.35);text-align:center;cursor:pointer';
      if (cur === pair[0]) { cell.style.borderColor = '#a8802e'; cell.style.boxShadow = '0 0 0 2px rgba(168,128,46,.2)'; }
      const demo = U.el('div', 'v3-bubble ' + (pair[0] === 'b1' ? '' : pair[0]));
      demo.style.cssText = 'position:static;display:inline-block;max-width:100%;pointer-events:none;'
        + 'transform:none;opacity:1;font-size:11px;padding:5px 9px';
      demo.textContent = '今天也要元气满满哦！';
      if (pair[0] === 'b4') {
        demo.style.backgroundImage = img ? 'url("' + img + '")' : 'none';
        if (!img) { demo.style.border = '1px dashed rgba(150,120,70,.6)'; demo.textContent = '还没传图'; }
      }
      cell.appendChild(demo);
      cell.appendChild(U.el('div', null, pair[1]));
      cell.onclick = function () {
        ctxRef.settings.set('bubbleStyle', pair[0]);
        applyBubbleStyle();
        uiRefresh();
      };
      prev.appendChild(cell);
    });
    box.appendChild(prev);

    const add = U.el('div', 'v3-addrow');
    const bPlus = U.el('button', 'v3-btn pri', '＋ 导入自己的气泡底图');
    bPlus.onclick = function () {
      pickOneImage(function (f) {
        readAsDataURL(f).then(function (d) {
          if (!d) return;
          BUBBLE_IMG = d;
          U.idb.put('pet:bubbleImg', d).catch(function () {});
          ctxRef.settings.set('bubbleStyle', 'b4');
          applyBubbleStyle();
          toast('气泡已换成你的图', 2200, 'ok');
          uiRefresh();
        });
      });
    };
    add.appendChild(bPlus);
    if (img) {
      const bDel = U.el('button', 'v3-btn dgr', '删掉这张图');
      bDel.onclick = function () {
        BUBBLE_IMG = '';
        U.idb.del('pet:bubbleImg').catch(function () {});
        ctxRef.settings.set('bubbleStyle', 'b1');
        applyBubbleStyle(); uiRefresh();
      };
      add.appendChild(bDel);
    }
    box.appendChild(add);
    host.appendChild(box);
    return null;
  }

  /* ======================================================================
   *  V3.3 —— 「心情表现」表（原来那张「心情值过低时动作」的合并升级版）
   *  一行 = 一个心情档位，四列：心情值 | 标签 | 台词 | 动作图片
   *    · 台词：一条一个栏位，最多 5 条，每条可设「出现概率」；
   *    · 动作图片：可以挂多张（你导入的动作图），也可设概率；不挂就按标签走内置图；
   *    · 标签：统一的可复用分类（默认「悲伤 / 开心」），能自定义，标签上带
   *      「心情值范围 / AI 聊天是否可用 / 视频聊天是否可用」—— 视频聊天可用的标签，
   *      它下面的动作图会自动出现在视频聊天动作库里。
   *  这一套同时服务「低落戏」（lowMoodTick）和帧选择（frameKey）。
   * ==================================================================== */
  /* 5 个内置情绪动作的中文名（原来只有英文 sigh/sad/beg/wipe/cry，现在中文在前、
     英文加括号跟在后面，界面上不再突然蹦出一串英文） */
  const ACT_CN = { sigh: '叹气', sad: '难过', beg: '眼巴巴', wipe: '擦眼泪', cry: '大哭' };
  function cnEn(cn, en) { return cn + '（' + en + '）'; }
  function actLabelOf(v) { return cnEn(ACT_CN[v] || (typeof ACT_LABEL !== 'undefined' && ACT_LABEL[v]) || v, v); }

  function defaultTags() {
    return [
      { id: 'sad',   label: '悲伤', min: 0,  max: 55,  low: true,  aiChat: true, videoChat: true },
      { id: 'happy', label: '开心', min: 78, max: 100, low: false, aiChat: true, videoChat: true }
    ];
  }
  /* 默认 8 行：悲伤 4 条 + 开心 4 条（第一列数值越高越靠上） */
  function defaultMoodRows() {
    return [
      { at: 100, tag: 'happy', lines: [{ text: '主人主人！今天也超——有精神！', prob: 1 }], imgs: [] },
      { at: 94,  tag: 'happy', lines: [{ text: '嘿嘿，看到你就想笑。', prob: 1 }], imgs: [] },
      { at: 88,  tag: 'happy', lines: [{ text: '要不要一起看点什么呀？', prob: 1 }], imgs: [] },
      { at: 82,  tag: 'happy', lines: [{ text: '我在旁边陪你，安心做事吧。', prob: 1 }], imgs: [] },
      { at: 55,  tag: 'sad',   lines: [{ text: '今天有点提不起劲呢…', prob: 1 }], imgs: [] },
      { at: 46,  tag: 'sad',   lines: [{ text: '主人是不是把我忘了呀…', prob: 1 }], imgs: [] },
      { at: 38,  tag: 'sad',   lines: [{ text: '呜…我自己擦一擦就好。', prob: 1 }], imgs: [] },
      { at: 30,  tag: 'sad',   lines: [{ text: '主人不搭理我啊……', prob: 1 }], imgs: [] }
    ];
  }
  let TAGS = defaultTags();
  let MOOD_ROWS = defaultMoodRows();
  /* 旧版本存的是「数值 | 动作 | 台词」，新版本存完整 JSON；两边都能读 */
  let MOOD_SHOW = MOOD_ROWS.map(function (r) {
    return { at: r.at, act: r.tag === 'happy' ? 'hum' : 'sad', sub: r.tag === 'happy' ? 'hum' : 'sad',
             line: (r.lines[0] && r.lines[0].text) || '……',
             dur: Math.max(3, 3 + (60 - r.at) * 0.16), tag: r.tag, lines: r.lines, imgs: r.imgs };
  });

  function tagById(id) {
    for (let i = 0; i < TAGS.length; i++) if (TAGS[i].id === id) return TAGS[i];
    return null;
  }
  function tagLabel(id) { const t = tagById(id); return t ? t.label : id; }
  function moodTagSub(tag) { return (tag && tag.low) ? 'sad' : 'hum'; }
  /* 概率权重抽签：items 里每项有 prob（缺省 1） */
  function weightedItem(items) {
    if (!items || !items.length) return null;
    let total = 0;
    items.forEach(function (o) { total += Math.max(0, Number(o.prob) || 0) || 0.0001; });
    let r = Math.random() * total;
    for (let i = 0; i < items.length; i++) {
      const w = Math.max(0, Number(items[i].prob) || 0) || 0.0001;
      r -= w;
      if (r <= 0) return items[i];
    }
    return items[items.length - 1];
  }
  function moodRowList() { return MOOD_ROWS.slice().sort(function (a, b) { return b.at - a.at; }); }
  /* 每行的「生效区间」是 (下一行, 本行]：所以取「at ≥ 当前心情」里最小的那一行。
     例：行 30/38/46/55，心情 40 → 命中 46 那一行；心情 20 → 命中 30 那一行。 */
  function moodRowFor(m, lowOnly) {
    const list = moodRowList();
    let hit = null;
    for (let i = 0; i < list.length; i++) {
      const t = tagById(list[i].tag);
      if (lowOnly && !(t && t.low)) continue;
      if (m <= list[i].at) hit = list[i];
    }
    return hit;
  }
  function lowTop() {
    let top = -1;
    MOOD_ROWS.forEach(function (r) { const t = tagById(r.tag); if (t && t.low && r.at > top) top = r.at; });
    return top;
  }
  /* 行里挂的动作图片 → 当成普通动作帧喂给绘制层（键名 row:<i>:<j>） */
  function rebuildRowImages() {
    MOOD_ROWS.forEach(function (r, i) {
      (r.imgs || []).forEach(function (im, j) {
        if (!im || !im.src) return;
        const k = 'row:' + i + ':' + j;
        if (ASRC[k] !== im.src) { delete AIMG[k]; ASRC[k] = im.src; }
      });
    });
  }
  /* 当前心情命中哪一行、该显哪张图（同一行内不每帧乱跳，换行才重抽） */
  function moodRowKey() {
    if (!MOOD_ROWS.length) return null;
    const row = moodRowFor(pet.mood, false);
    if (!row) return null;
    const imgs = (row.imgs || []).filter(function (o) { return o && o.src; });
    if (!imgs.length) return null;
    const idx = MOOD_ROWS.indexOf(row);
    if (pet.rowPicked !== row) {
      pet.rowPicked = row;
      const pick = weightedItem(imgs);
      pet.rowImgIdx = Math.max(0, imgs.indexOf(pick));
    }
    const hit = imgs[U.clamp(pet.rowImgIdx || 0, 0, imgs.length - 1)];
    if (!hit) return null;
    return 'row:' + idx + ':' + (row.imgs.indexOf(hit));
  }
  function saveMoodRows() {
    MOOD_ROWS.sort(function (a, b) { return b.at - a.at; });
    rebuildRowImages();
    try { ms('moodRows', JSON.stringify(MOOD_ROWS)); } catch (e) {}
    try { ms('moodTags', JSON.stringify(TAGS)); } catch (e) {}
    /* 旧的文本格式一并写出去：万一有人用旧版本打开也能读回大致的档位 */
    MOOD_SHOW = MOOD_ROWS.map(function (r) {
      const t = tagById(r.tag);
      return { at: r.at, act: moodTagSub(t), sub: moodTagSub(t),
               line: (r.lines[0] && r.lines[0].text) || '……',
               dur: Math.max(3, 3 + (60 - r.at) * 0.16), tag: r.tag, lines: r.lines, imgs: r.imgs };
    });
    try {
      ms('moodShowList',
        MOOD_ROWS.map(function (r) { return r.at + ' | ' + moodTagSub(tagById(r.tag)) + ' | '
          + ((r.lines[0] && r.lines[0].text) || '……'); }).join('\n'));
    } catch (e) {}
  }
  function loadMoodRows() {
    if (!ctxRef) return;
    let ok = false;
    try {
      const t = mg('moodTags', '');
      if (t) { const a = JSON.parse(t); if (Array.isArray(a) && a.length) { TAGS = a; ok = true; } }
      const r = mg('moodRows', '');
      if (r) {
        const a = JSON.parse(r);
        if (Array.isArray(a) && a.length) {
          MOOD_ROWS = a.map(function (o) {
            return { at: U.clamp(Number(o.at) || 50, 0, 100), tag: o.tag || 'sad',
                     lines: (o.lines || []).map(function (l) {
                       return typeof l === 'string' ? { text: l, prob: 1 }
                            : { text: String((l && l.text) || ''), prob: Number(l && l.prob) || 1 };
                     }).slice(0, 5),
                     imgs: (o.imgs || []).map(function (m) {
                       return typeof m === 'string' ? { src: m, prob: 1 }
                            : { src: String((m && m.src) || ''), prob: Number(m && m.prob) || 1 };
                     }) };
          });
          ok = true;
        }
      }
    } catch (e) { console.warn('[女仆] 心情表现表读取失败，用默认值', e); }
    if (!ok) {
      /* 兼容更早版本：只有「数值 | 动作 | 台词」的文本表 */
      const legacy = String(mg('moodShowList', '') || '').trim();
      if (legacy) {
        const out = [];
        legacy.split('\n').forEach(function (ln) {
          const m = String(ln).trim().match(/^(\d{1,3})\s*[|,，\t ]\s*([A-Za-z_]+)\s*(?:[|,，\t]\s*([^|]*))?/);
          if (!m) return;
          out.push({ at: U.clamp(Number(m[1]), 0, 100),
                     tag: /sigh|sad|beg|wipe|cry/.test(m[2]) ? 'sad' : 'happy',
                     lines: [{ text: (m[3] || '').trim() || '……', prob: 1 }], imgs: [] });
        });
        if (out.length) { TAGS = defaultTags(); MOOD_ROWS = out; ok = true; }
      }
    }
    if (!ok) { TAGS = defaultTags(); MOOD_ROWS = defaultMoodRows(); }
    if (!TAGS.length) TAGS = defaultTags();
    MOOD_ROWS.forEach(function (r) {
      if (!r.lines || !r.lines.length) r.lines = [{ text: '……', prob: 1 }];
    });
    MOOD_ROWS.sort(function (a, b) { return b.at - a.at; });
    rebuildRowImages();
  }

  /* ---- 「心情表现」面板（原「心情值过低时动作」，V3.3 合并升级）---- */
  function buildMoodPanel(host) {
    if (!ctxRef) return null;
    const box = U.el('div');
    box.innerHTML = '<div class="v3-note">这就是「<b>不同心情值所对应的表现</b>」，也是原来那张'
      + '「心情值过低时动作」的合并升级版。四列：<b>心情值 → 标签 → 台词 → 动作图片</b>。'
      + '心情掉到某个数值以下，就演那一行。<br>'
      + '<b>台词</b>一条一个输入框；写下一句的时候左边会多出一个小 <b>＋</b>（一行最多 5 条），'
      + '每条台词后面的小数字是<b>出现概率</b>；<b>动作图片</b>可从你导入的动作图里挑多张挂上，'
      + '也能设概率 —— 一张都不挂就按标签走内置动作图。<br>'
      + '最后一档（最低那一行）演完之后，女仆会<b>躺下睡 2~3 分钟</b>，醒来回到设定值。</div>';

    const tbl = U.el('div');
    tbl.style.cssText = 'overflow-x:auto';
    const t = U.el('table', 'v3-mt');
    t.innerHTML = '<thead><tr><th class="c-at">心情值</th><th class="c-tag">标签</th>'
      + '<th>台词（最多 5 条 · 可设概率）</th><th>动作图片（可多张 · 可设概率）</th>'
      + '<th class="c-del"></th></tr></thead>';
    const tb = U.el('tbody');
    moodRowList().forEach(function (r) { tb.appendChild(moodTableRow(r)); });
    t.appendChild(tb);
    tbl.appendChild(t);
    box.appendChild(tbl);

    /* ＋ 新增一档：心情值 + 类型（标签）+ 台词 + 动作图片（都齐了） */
    const add = U.el('div', 'v3-addrow');
    add.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-top:8px';
    const nAt = U.el('input');
    nAt.type = 'number'; nAt.min = 0; nAt.max = 100; nAt.value = 25;
    nAt.placeholder = '心情值';
    nAt.style.cssText = 'flex:0 0 66px;border:1px solid rgba(168,128,46,.35);border-radius:5px;'
      + 'background:#fffdf6;color:inherit;font-size:11.5px;padding:4px 6px';
    const nTag = U.el('select');
    nTag.style.cssText = nAt.style.cssText.replace('flex:0 0 66px', 'flex:0 0 90px');
    TAGS.forEach(function (tg) {
      const o = U.el('option', null, U.esc(tg.label)); o.value = tg.id; nTag.appendChild(o);
    });
    const nTxt = U.el('input');
    nTxt.type = 'text';
    nTxt.placeholder = '＋ 第一句台词';
    nTxt.style.cssText = 'flex:1 1 130px;min-width:110px;border:1px solid rgba(168,128,46,.35);'
      + 'border-radius:5px;background:#fffdf6;color:inherit;font-size:11.5px;padding:4px 7px';
    const nImgBtn = U.el('button', 'v3-btn', '＋ 动作图片');
    nImgBtn.title = '给这一档挑一张动作图（可以挑多次）';
    let nImgs = [];
    nImgBtn.onclick = function () {
      pickOneImage(function (f) {
        readAsDataURL(f).then(function (d) {
          if (!d) return;
          nImgs.push({ src: d, prob: 1 });
          nImgBtn.textContent = '＋ 动作图片（已选 ' + nImgs.length + '）';
        });
      });
    };
    const bAdd = U.el('button', 'v3-btn pri', '加入');
    const doAdd = function () {
      const at = U.clamp(Number(nAt.value) || 25, 0, 100);
      MOOD_ROWS.push({ at: at, tag: nTag.value || 'sad',
                       lines: [{ text: nTxt.value.trim() || '……', prob: 1 }],
                       imgs: nImgs.slice() });
      saveMoodRows(); refreshPanel();
    };
    bAdd.onclick = doAdd;
    nTxt.addEventListener('keydown', function (e) { e.stopPropagation(); if (e.key === 'Enter') doAdd(); });
    add.appendChild(nAt); add.appendChild(nTag); add.appendChild(nTxt);
    add.appendChild(nImgBtn); add.appendChild(bAdd);
    box.appendChild(add);

    /* 标签管理（自定义标签 = 参考动作标签的设置：心情范围 + AI 聊天可用 + 视频聊天可用） */
    box.appendChild(buildTagBox());

    host.appendChild(box);
    return null;
  }

  /* 表格里的「一行」：心情值 | 标签 | 台词（≤5） | 动作图片 | 删除 */
  function moodTableRow(r) {
    const tr = U.el('tr', 'v3-mrow');
    const td1 = U.el('td');
    const num = U.el('input', 'num');
    num.type = 'number'; num.min = 0; num.max = 100; num.value = r.at;
    num.onchange = function () { r.at = U.clamp(Number(num.value) || 0, 0, 100); saveMoodRows(); refreshPanel(); };
    td1.appendChild(num);
    tr.appendChild(td1);

    const td2 = U.el('td');
    const sel = U.el('select');
    TAGS.forEach(function (tg) {
      const o = U.el('option', null, U.esc(tg.label)); o.value = tg.id;
      if (tg.id === r.tag) o.selected = true;
      sel.appendChild(o);
    });
    sel.onchange = function () { r.tag = sel.value; saveMoodRows(); refreshPanel(); };
    td2.appendChild(sel);
    tr.appendChild(td2);

    /* 台词列：每条一个框（内容 + 概率），写了一条就出现小 ＋ */
    const td3 = U.el('td');
    (r.lines || []).forEach(function (l, li) {
      const row = U.el('div', 'v3-mline');
      const ti = U.el('input');
      ti.type = 'text'; ti.value = l.text || '';
      ti.placeholder = '台词 ' + (li + 1);
      ti.onchange = function () { l.text = ti.value.replace(/\n/g, ' ') || '……'; saveMoodRows(); };
      const pi = U.el('input', 'prob');
      pi.type = 'number'; pi.min = 0; pi.max = 100; pi.step = 1;
      pi.value = Math.round((Number(l.prob) || 0) * 100);
      pi.title = '这条台词的出现概率（%，同一行里按比例抽）';
      pi.onchange = function () { l.prob = U.clamp((Number(pi.value) || 0) / 100, 0, 1); saveMoodRows(); };
      const bp = U.el('button', 'v3-plus', '＋');
      bp.title = (r.lines.length >= 5) ? '一行最多 5 条台词' : '再加一条台词';
      bp.disabled = r.lines.length >= 5;
      bp.onclick = function () {
        if (r.lines.length >= 5) return;
        r.lines.push({ text: '', prob: 1 });
        saveMoodRows(); refreshPanel();
      };
      const bd = U.el('button', 'v3-mini', '✕');
      bd.title = '删掉这条台词';
      bd.onclick = function () {
        if (r.lines.length <= 1) { toast('每行至少留一条台词', 1800); return; }
        r.lines.splice(li, 1); saveMoodRows(); refreshPanel();
      };
      row.appendChild(ti); row.appendChild(pi); row.appendChild(bp); row.appendChild(bd);
      td3.appendChild(row);
    });
    td3.appendChild(U.el('div', 'v3-note', '共 ' + r.lines.length + '/5 条 · 概率相加后按比例抽'));
    tr.appendChild(td3);

    /* 动作图片列 */
    const td4 = U.el('td');
    (r.imgs || []).forEach(function (im, ii) {
      const row = U.el('div', 'v3-imline');
      const th = U.el('div', 'v3-ithumb');
      th.style.backgroundImage = 'url("' + im.src + '")';
      th.title = '点一下换成别的图';
      th.onclick = function () {
        pickOneImage(function (f) {
          readAsDataURL(f).then(function (d) {
            if (!d) return;
            im.src = d;
            delete AIMG['row:' + MOOD_ROWS.indexOf(r) + ':' + ii];
            ASRC['row:' + MOOD_ROWS.indexOf(r) + ':' + ii] = d;
            saveMoodRows(); refreshPanel();
          });
        });
      };
      const pi = U.el('input', 'prob');
      pi.type = 'number'; pi.min = 0; pi.max = 100;
      pi.value = Math.round((Number(im.prob) || 0) * 100);
      pi.title = '这张图在本次出现里的概率（%）';
      pi.onchange = function () { im.prob = U.clamp((Number(pi.value) || 0) / 100, 0, 1); saveMoodRows(); };
      const bd = U.el('button', 'v3-mini', '✕');
      bd.onclick = function () { r.imgs.splice(ii, 1); saveMoodRows(); refreshPanel(); };
      row.appendChild(th); row.appendChild(pi); row.appendChild(bd);
      td4.appendChild(row);
    });
    const bp = U.el('button', 'v3-plus', '＋');
    bp.title = '给这一档挂一张动作图（可多张）';
    bp.onclick = function () {
      pickOneImage(function (f) {
        readAsDataURL(f).then(function (d) {
          if (!d) return;
          if (!r.imgs) r.imgs = [];
          r.imgs.push({ src: d, prob: 1 });
          saveMoodRows(); refreshPanel();
        });
      });
    };
    td4.appendChild(bp);
    if (!(r.imgs || []).length) td4.appendChild(U.el('div', 'v3-note', '不挂图 → 按标签走内置图'));
    tr.appendChild(td4);

    const td5 = U.el('td');
    const bD = U.el('button', 'v3-mini', '✕');
    bD.title = '删掉这一档';
    bD.onclick = function () {
      const i = MOOD_ROWS.indexOf(r);
      if (i >= 0) MOOD_ROWS.splice(i, 1);
      saveMoodRows(); refreshPanel();
    };
    td5.appendChild(bD);
    tr.appendChild(td5);
    return tr;
  }

  /* 标签管理：默认「悲伤 / 开心」，下面小 ＋ 自己加；自定义标签要设心情范围、
     AI 聊天是否可用、视频聊天是否可用（和动作的自定义标签一个路数）。 */
  function buildTagBox() {
    const wrap = U.el('details', 'v3-help');
    wrap.appendChild(U.el('summary', null, '标签设置（默认悲伤 / 开心 · 可自定义 · 当前 ' + TAGS.length + ' 个）'));
    const bd = U.el('div', 'v3-help-bd');
    bd.appendChild(U.el('div', 'v3-note',
      '标签是给「心情档位」分类用的，也能被 AI 聊天 / 视频聊天引用。'
      + '打开 <b>视频聊天可用</b> 之后，这个标签下挂的动作图会自动出现在视频聊天动作库里。'));

    const box = U.el('div', 'v3-tagbox');
    TAGS.forEach(function (tg) {
      const row = U.el('div', 'v3-tgrow');
      const nm = U.el('input');
      nm.type = 'text'; nm.value = tg.label || tg.id;
      nm.onchange = function () { tg.label = nm.value.trim() || tg.id; saveMoodRows(); refreshPanel(); };
      const lo = U.el('input');
      lo.type = 'number'; lo.min = 0; lo.max = 100; lo.value = tg.min != null ? tg.min : 0;
      lo.title = '这个标签覆盖的心情值下限';
      lo.onchange = function () { tg.min = U.clamp(Number(lo.value) || 0, 0, 100); saveMoodRows(); refreshPanel(); };
      const hi = U.el('input');
      hi.type = 'number'; hi.min = 0; hi.max = 100; hi.value = tg.max != null ? tg.max : 100;
      hi.title = '这个标签覆盖的心情值上限';
      hi.onchange = function () { tg.max = U.clamp(Number(hi.value) || 0, 0, 100); saveMoodRows(); refreshPanel(); };
      const mkSw = function (on, tip, fn) {
        const s = U.el('span', 'v3-chip' + (on ? ' on' : ''), tip);
        s.onclick = function () { fn(!on); };
        return s;
      };
      row.appendChild(nm);
      row.appendChild(U.el('span', null, '心情'));
      row.appendChild(lo);
      row.appendChild(U.el('span', null, '~'));
      row.appendChild(hi);
      row.appendChild(mkSw(tg.aiChat !== false, 'AI 聊天', function (v) { tg.aiChat = v; saveMoodRows(); refreshPanel(); }));
      row.appendChild(mkSw(tg.videoChat !== false, '视频聊天', function (v) { tg.videoChat = v; saveMoodRows(); refreshPanel(); }));
      row.appendChild(mkSw(!!tg.low, '低落侧', function (v) { tg.low = v; saveMoodRows(); refreshPanel(); }));
      const del = U.el('button', 'v3-mini', '✕');
      del.title = '删掉这个标签';
      del.onclick = function () {
        if (TAGS.length <= 1) { toast('至少留一个标签', 1800); return; }
        const i = TAGS.indexOf(tg);
        TAGS.splice(i, 1);
        MOOD_ROWS.forEach(function (r) { if (r.tag === tg.id) r.tag = TAGS[0].id; });
        saveMoodRows(); refreshPanel();
      };
      row.appendChild(del);
      box.appendChild(row);
    });
    const addRow = U.el('div', 'v3-tgrow');
    const nInp = U.el('input');
    nInp.type = 'text'; nInp.placeholder = '新标签名';
    const nB = U.el('button', 'v3-miniadd', '＋ 新增标签');
    nB.onclick = function () {
      const name = nInp.value.trim();
      if (!name) { toast('先写个标签名', 1800); return; }
      const id = 't' + Date.now().toString(36).slice(-5);
      TAGS.push({ id: id, label: name, min: 0, max: 100, low: false, aiChat: true, videoChat: true });
      saveMoodRows(); refreshPanel();
    };
    addRow.appendChild(nInp); addRow.appendChild(nB);
    box.appendChild(addRow);
    bd.appendChild(box);
    wrap.appendChild(bd);
    return wrap;
  }
  /* 旧名字保留：别的地方（含验收脚本）还在调它 */
  function saveMoodShow() { saveMoodRows(); }

  /* ---- 女仆头像图标：按项目主题画一个「十字星棱」，用作模块图标 ---- */
  function starIconDataUrl(px) {
    try {
      const c = document.createElement('canvas');
      const S = px || 96;
      c.width = S; c.height = S;
      const q = c.getContext('2d');
      q.clearRect(0, 0, S, S);
      const R = S * 0.46, r = S * 0.15;
      q.save(); q.translate(S / 2, S / 2);
      q.beginPath();
      for (let i = 0; i < 4; i++) {
        const a = -Math.PI / 2 + i * Math.PI / 2;
        const x1 = Math.cos(a) * R, y1 = Math.sin(a) * R;
        const b1 = a + Math.PI / 4, b2 = a - Math.PI / 4;
        const cx1 = Math.cos(b1) * r, cy1 = Math.sin(b1) * r;
        const cx2 = Math.cos(b2) * r, cy2 = Math.sin(b2) * r;
        if (i === 0) q.moveTo(x1, y1);
        else q.lineTo(x1, y1);
        q.quadraticCurveTo(cx1, cy1, Math.cos(a + Math.PI / 2) * R, Math.sin(a + Math.PI / 2) * R);
      }
      q.closePath();
      const grd = q.createLinearGradient(-R, -R, R, R);
      grd.addColorStop(0, '#8fb4e8'); grd.addColorStop(1, '#2b3a67');
      q.fillStyle = grd; q.fill();
      q.lineWidth = S * 0.035; q.strokeStyle = '#f8f5ec'; q.stroke();
      q.beginPath(); q.arc(-S * 0.08, -S * 0.10, S * 0.05, 0, 6.2832);
      q.fillStyle = 'rgba(255,255,255,.9)'; q.fill();
      q.restore();
      return c.toDataURL('image/png');
    } catch (e) { return ''; }
  }

  /* ---- 主绘制入口 ---- */
  const MOOD_PINK = ['#ff9ec4', '#ff7aa8', '#f2557f', '#c9345f'];   /* 高 → 低，都是粉 */
  function moodColor(m) {
    const k = U.clamp(m, 0, 1);
    if (k > 0.72) return MOOD_PINK[0];
    if (k > 0.5) return MOOD_PINK[1];
    if (k > 0.34) return MOOD_PINK[2];
    return MOOD_PINK[3];
  }
  /* 心情条在「头顶」的正上方（贴着所在轨道的朝向）—— 贴在墙上时它是竖的 */
  function moodBarBox(size) {
    const h = 186 * size;
    const d = headDir();
    const w = 30, th = 5;
    const cx = pet.x + d.x * (h + 16);
    const cy = pet.y - (pet.hop || 0) - (pet.bob || 0) + d.y * (h + 16);
    if (d.x) return { x: cx - th / 2, y: cy - w / 2, w: th, h: w, vert: true };
    return { x: cx - w / 2, y: cy - th / 2, w: w, h: th, vert: false };
  }

  function render() {
    if (!g || !cv) return;
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.clearRect(0, 0, cv.width, cv.height);
    g.scale(DPR, DPR);
    /* 过场特效：形象包用通用粒子，纸娃娃用「程序化穿越门」（画风才对得上） */
    if (jumping && !travelOn()) {
      if (usePack()) drawJumpFx(g);
      else drawTravelGate(g);
    }
    /* 过场大图升起来之后，画布上什么都不留（本体让位给那张插画） */
    if (!travelOn()) {
      /* 装了形象包就画图片（默认就是内置的「主星女仆」），否则退回程序化纸娃娃 */
      if (!(usePack() && drawSprite(g))) drawPet(g, 1);
    }
    /* 过场期间（大图已经升起来）不再画心情条和热区，免得压在过场画面上 */
    if (pet.showMood && !jumping) {
      const sz = U.clamp(Number(ctxRef.settings.get('size', 1)) || 1, 0.6, 1.8);
      const b = moodBarBox(sz);
      const m = U.clamp(pet.mood / 100, 0, 1);
      g.save();
      g.globalAlpha = 0.92;
      rr(g, b.x - 1, b.y - 1, b.w + 2, b.h + 2, 3);
      g.fillStyle = 'rgba(60,34,48,.30)'; g.fill();
      if (b.vert) {
        const hgt = b.h * m;
        rr(g, b.x, b.y + b.h - hgt, b.w, hgt, 2.4);
      } else {
        rr(g, b.x, b.y, b.w * m, b.h, 2.4);
      }
      g.fillStyle = moodColor(m); g.fill();
      /* 睡觉时给心情条加一层柔光，一眼能看出她在休息 */
      if (pet.asleep > 0) {
        g.globalAlpha = 0.35 + Math.sin(pet.t * 2.4) * 0.2;
        rr(g, b.x - 2.5, b.y - 2.5, b.w + 5, b.h + 5, 4);
        g.strokeStyle = '#ffd0e2'; g.lineWidth = 1.6; g.stroke();
      }
      g.restore();
    }
    /* 每帧把视频聊天窗口的画面刷新一遍（开着才画，开销可忽略） */
    pipSync();
  }

  /* ======================= 9.5 女仆条目（一级列表 / 二级个性化设置）=======================
     【V3.3】原来所有设置都摊在一层，只有一个「角色本体」。现在收成两级的「女仆」条目：
       一级 = 女仆列表（主星女仆 / 程序纸女仆 / 你自己创建的角色）
       二级 = 点某个女仆之后，她的个性化设置（图片、语音动作、心情表现、台词、视频聊天台词库、
              服装、动作频率、AI 聊天设置、气泡选择、睡觉设置…）
     所有二级设置都按「女仆 id」分开存：换一个女仆，她那套台词/心情/动作频率就跟着换。
     老用户原来的设置全部落在「主星女仆」名下（mg 会先读 maid.<id>.<k>，读不到就退回全局键）。
  ================================================================================== */
  const MAID_BUILTIN = [
    { id: 'main', name: '主星女仆', kind: 'pack',
      desc: '内置形象包 · 12 张动作图 + 32 张语音动作帧 + 6 张穿越图（十字星棱女仆）' },
    { id: 'doll', name: '程序纸女仆', kind: 'doll',
      desc: '程序化纸娃娃 · 不依赖任何图片，靠参数画出来；发色 / 换装方式 / 配饰只在纸娃娃下有效' }
  ];
  let MAIDS = [];
  let curMaid = 'main';
  function maidById(id) {
    for (let i = 0; i < MAIDS.length; i++) if (MAIDS[i].id === id) return MAIDS[i];
    return null;
  }
  function curMaidRec() { return maidById(curMaid) || MAIDS[0] || null; }
  function maidData(id) {
    const m = maidById(id || curMaid);
    if (!m) return {};
    if (!m.data) m.data = {};
    return m.data;
  }
  /* 二级设置的读写：先看这个女仆自己的（maid.<id>.<k>），没有就退回全局键 ——
     这样老用户原来的设置天然落在「主星女仆」名下，新女仆也可以引用/覆盖其中任意一项。 */
  function mg(k, d) {
    if (!ctxRef) return d;
    const v = ctxRef.settings.get('maid.' + curMaid + '.' + k);
    if (v !== undefined && v !== '') return v;
    const g = ctxRef.settings.get(k);
    if (g !== undefined && g !== '') return g;
    return d;
  }
  function ms(k, v) { if (ctxRef) ctxRef.settings.set('maid.' + curMaid + '.' + k, v); }
  function loadMaids() {
    if (!ctxRef) return;
    MAIDS = MAID_BUILTIN.map(function (m) { return { id: m.id, name: m.name, kind: m.kind, desc: m.desc }; });
    try {
      const raw = ctxRef.settings.get('maidsCustom', '');
      if (raw) {
        const a = JSON.parse(raw);
        if (Array.isArray(a)) a.forEach(function (m) {
          if (m && m.id && m.name) MAIDS.push({ id: m.id, name: m.name, kind: 'custom',
            desc: m.desc || ('你创建的角色 · ' + (m.lines || []).length + ' 句台词'), data: m.data || {} });
        });
      }
      const act = ctxRef.settings.get('activeMaid', '');
      if (act && maidById(act)) curMaid = act;
    } catch (e) { console.warn('[女仆] 女仆列表读取失败', e); }
  }
  function saveMaids() {
    if (!ctxRef) return;
    const out = MAIDS.filter(function (m) { return m.kind === 'custom'; }).map(function (m) {
      return { id: m.id, name: m.name, desc: m.desc, data: m.data || {} };
    });
    try { ctxRef.settings.set('maidsCustom', JSON.stringify(out)); } catch (e) {}
    try { ctxRef.settings.set('activeMaid', curMaid); } catch (e) {}
  }
  /* 切换当前女仆：形象模式 / 发色 / 台词 / 心情 / 视频台词 全部跟着换 */
  function setActiveMaid(id) {
    if (!maidById(id)) return;
    curMaid = id;
    saveMaids();
    const m = maidById(id);
    if (m.kind === 'doll') ctxRef.settings.set('skinMode', 'doll');
    else ctxRef.settings.set('skinMode', 'pack');
    /* 纸娃娃专属：发色 / 换装方式 / 配饰 */
    pet.hairColor = mg('hairColor', 'black');
    loadMoodRows();
    loadVideoChat();
    applyCostume(APP.getYear(), true);
    applyBubbleStyle();
    if (m.kind === 'custom') loadMaidSprites(m);
    else if (m.kind === 'main') loadBuiltinPack();
    else { /* 程序纸女仆：清掉形象包，退回参数化绘制 */ }
    toast('已切到「' + m.name + '」', 2200, 'ok');
    refreshPanel();
  }
  /* 自定义女仆：把她自己的 12 张图从 IndexedDB 读进 SPRITE 池 */
  function loadMaidSprites(m) {
    SPRITE_SLOTS.forEach(function (s) {
      delete SPRITE[s.key]; delete SPRITE_SRC[s.key]; delete SPRITE_BUILTIN[s.key];
    });
    const jobs = SPRITE_SLOTS.map(function (s) {
      return U.idb.get('maid:' + m.id + ':' + s.key).then(function (d) {
        if (d) return loadSprite(s.key, d);
      }).catch(function () {});
    });
    Promise.all(jobs).then(function () { refreshPanel(); });
  }
  function saveMaidSprites(m, key, dataUrl) {
    return U.idb.put('maid:' + m.id + ':' + key, dataUrl).catch(function () {});
  }

  /* ---- 动作频率：分 13 种（内置 12 个动作 + 其他动作），视频聊天另外算 ---- */
  const FREQ_KINDS = [
    { id: 'body',    label: '本体 · 站立',   en: 'body',    subs: ['daze'] },
    { id: 'talk',    label: '说话中',       en: 'talk',    subs: ['hum'] },
    { id: 'explain', label: '讲解知识',     en: 'explain', subs: ['think'] },
    { id: 'smile',   label: '微笑温柔',     en: 'smile',   subs: ['dress'] },
    { id: 'happy',   label: '喜悦 · 跳跃欢呼', en: 'joy',    subs: ['play', 'hop'] },
    { id: 'excited', label: '兴奋跳跃',     en: 'excited', subs: ['stretch'] },
    { id: 'dance',   label: '跳舞旋转',     en: 'dance',   subs: ['spin'] },
    { id: 'walk',    label: '散步',         en: 'walk',    subs: ['walk'] },
    { id: 'proud',   label: '傲娇',         en: 'proud',   subs: ['look'] },
    { id: 'angry',   label: '愤怒跺脚',     en: 'angry',   subs: ['wave'] },
    { id: 'sad',     label: '悲伤抱膝',     en: 'sad',     subs: ['sad'] },
    { id: 'cry',     label: '大哭崩溃',     en: 'cry',     subs: ['cry'] },
    { id: 'other',   label: '其他动作',     en: 'other',   subs: ['sit', 'read', 'drink', 'work'] }
  ];
  function maidFreq() {
    let f = mg('freq', null);
    if (typeof f === 'string') { try { f = JSON.parse(f); } catch (e) { f = null; } }
    if (!f || typeof f !== 'object') f = {};
    FREQ_KINDS.forEach(function (k) { if (f[k.id] == null) f[k.id] = 1; });
    return f;
  }
  function maidFreqOf(subId) {
    const f = maidFreq();
    for (let i = 0; i < FREQ_KINDS.length; i++) {
      if (FREQ_KINDS[i].subs.indexOf(subId) >= 0) return Number(f[FREQ_KINDS[i].id]) || 0;
    }
    return 1;
  }


  /* ---- 女仆角色包：导出 / 导入（2026-10-12 任务四）----
     角色包 = 名字与简介 + 个性化数据 + maid.<id>.* 全部专属设置 + 形象图。
     导入时分配新 id，全部内容落到新女仆名下，立刻可用。 */
  async function exportMaidPack(m) {
    try {
      let all = {};
      try { all = ctxRef.settings.all() || {}; }
      catch (e) {
        try { all = JSON.parse(localStorage.getItem(ctxRef.settings.key) || '{}') || {}; } catch (e2) { }
      }
      const pre = 'maid.' + m.id + '.';
      const settings = {};
      for (const k in all) {
        if (Object.prototype.hasOwnProperty.call(all, k) && k.indexOf(pre) === 0) {
          settings[k.slice(pre.length)] = all[k];
        }
      }
      const sprites = {};
      for (const s of SPRITE_SLOTS) {
        try {
          const d = await U.idb.get('maid:' + m.id + ':' + s.key);
          if (d) sprites[s.key] = d;
        } catch (e) { }
      }
      const pack = {
        format: 'maidpack', version: 1, exportedAt: new Date().toISOString(),
        name: m.name, desc: m.desc || '', kind: m.kind,
        data: m.data || {}, settings: settings, sprites: sprites
      };
      const blob = new Blob([JSON.stringify(pack, null, 1)], { type: 'application/json' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = '女仆角色包 - ' + (m.name || '未命名') + '.json';
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(function () { URL.revokeObjectURL(a.href); }, 4000);
      toast('已导出「' + m.name + '」的角色包', 2600, 'ok');
    } catch (e) {
      toast('导出失败：' + (e && e.message || e), 3400, 'err');
    }
  }
  function readMaidPackFile(f) {
    const r = new FileReader();
    r.onload = function () {
      try { importMaidPack(JSON.parse(String(r.result))); }
      catch (e) { toast('角色包解析失败：' + (e && e.message || e), 3400, 'err'); }
    };
    r.onerror = function () { toast('角色包读取失败', 3200, 'err'); };
    r.readAsText(f, 'utf-8');
  }
  async function importMaidPack(pack) {
    try {
      if (!pack || pack.format !== 'maidpack') {
        toast('这不是有效的女仆角色包（缺 format: maidpack）', 3400, 'err'); return;
      }
      const id = 'm' + Date.now().toString(36);
      const rec = {
        id: id, name: pack.name || '导入的女仆', kind: 'custom',
        desc: pack.desc || ('来自角色包 · ' + Object.keys(pack.sprites || {}).length + ' 张形象图'),
        data: pack.data || {}
      };
      MAIDS.push(rec);
      const pre = 'maid.' + id + '.';
      for (const k in (pack.settings || {})) {
        if (Object.prototype.hasOwnProperty.call(pack.settings, k)) {
          try { ctxRef.settings.set(pre + k, pack.settings[k]); } catch (e) { }
        }
      }
      for (const skey in (pack.sprites || {})) {
        if (Object.prototype.hasOwnProperty.call(pack.sprites, skey)) {
          try { await U.idb.put('maid:' + id + ':' + skey, pack.sprites[skey]); } catch (e) { }
        }
      }
      saveMaids();
      toast('已导入「' + rec.name + '」，正在为她布置房间…', 2400, 'ok');
      setActiveMaid(id);
      refreshPanel();
    } catch (e) {
      toast('导入失败：' + (e && e.message || e), 3400, 'err');
    }
  }

  /* ---- 一级：女仆列表 ---- */
