    const thImp = U.el('div', 'v3-maid-t');
    thImp.textContent = '＋';
    thImp.style.cssText = 'display:flex;align-items:center;justify-content:center;font-size:26px;color:#8a6a2e';
    impCard.appendChild(thImp);
    const infImp = U.el('div', 'v3-maid-i');
    infImp.innerHTML = '<b>导入女仆角色包</b><i>点这里选文件，或把角色包直接拖进这张卡片</i>';
    impCard.appendChild(infImp);
    const impIn = U.el('input');
    impIn.type = 'file'; impIn.accept = '.json,application/json'; impIn.style.display = 'none';
    impIn.onchange = function () {
      if (impIn.files && impIn.files[0]) readMaidPackFile(impIn.files[0]);
      impIn.value = '';
    };
    impCard.onclick = function () { impIn.click(); };
    impCard.ondragover = function (e) { e.preventDefault(); impCard.classList.add('on'); };
    impCard.ondragleave = function () { impCard.classList.remove('on'); };
    impCard.ondrop = function (e) {
      e.preventDefault(); impCard.classList.remove('on');
      const f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
      if (f) readMaidPackFile(f);
    };
    impCard.appendChild(impIn);
    box.appendChild(impCard);

    const bar = U.el('div');
    bar.style.cssText = 'display:flex;gap:8px;margin-top:8px;flex-wrap:wrap';
