          box.appendChild(U.el('div', 'v3-note', '女仆的性格描述（作为 system 提示词喂给接口，随你改）：'));
          const ta = U.el('textarea', 'v3-ta');
          ta.style.minHeight = '130px';
          ta.value = ctxRef.settings.get('aiPersona', '') || AI_DEFAULT_PERSONA;
          ta.onchange = function () { ctxRef.settings.set('aiPersona', ta.value); };
          box.appendChild(ta);
          const b = U.el('button', 'v3-btn', '恢复默认人设');
          b.onclick = function () { ta.value = AI_DEFAULT_PERSONA; ctxRef.settings.set('aiPersona', ta.value); };
